using AAEmu.Zone.Protocol.Messages;

namespace AAEmu.Zone.Tests;

public sealed class UnitStateSnapshotTests
{
    // WZUnitState body World sent for the first player entry (Zonetest, zone 129), from a live wzproxy capture.
    private const string PlayerEnterBody =
        "";

    [Test]
    public async Task PlayerEnterAcceptsZeroPaddedActiveExpertise()
    {
        var snapshot = UnitStateSnapshot.Read(Convert.FromHexString(PlayerEnterBody));
        await Assert.That(snapshot.Name).IsEqualTo("Zonetest");
        await Assert.That(snapshot.Character).IsNotNull();
        await Assert.That(snapshot.Character!.ActiveExpertise.SequenceEqual(new byte[] { 1, 0, 0 })).IsTrue();
    }
}
